#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

enum { BUCKET_COUNT = 7 };

struct Entry {
    unsigned int key;
    int value;
    struct Entry *next;
};

struct HashTable {
    struct Entry *buckets[BUCKET_COUNT];
    size_t size;
};

static size_t bucket_index(unsigned int key)
{
    return (size_t)(key % BUCKET_COUNT);
}

static bool table_put(struct HashTable *table, unsigned int key, int value)
{
    if (table == NULL) return false;

    size_t index = bucket_index(key);
    for (struct Entry *entry = table->buckets[index];
         entry != NULL; entry = entry->next) {
        if (entry->key == key) {
            entry->value = value;
            return true;
        }
    }

    struct Entry *entry = malloc(sizeof *entry);
    if (entry == NULL) return false;

    entry->key = key;
    entry->value = value;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    ++table->size;
    return true;
}

static bool table_get(const struct HashTable *table,
                      unsigned int key, int *value_out)
{
    if (table == NULL || value_out == NULL) return false;

    size_t index = bucket_index(key);
    for (const struct Entry *entry = table->buckets[index];
         entry != NULL; entry = entry->next) {
        if (entry->key == key) {
            *value_out = entry->value;
            return true;
        }
    }
    return false;
}

static bool table_remove(struct HashTable *table, unsigned int key)
{
    if (table == NULL) return false;

    size_t index = bucket_index(key);
    struct Entry **link = &table->buckets[index];

    while (*link != NULL && (*link)->key != key) {
        link = &(*link)->next;
    }
    if (*link == NULL) return false;

    struct Entry *removed = *link;
    *link = removed->next;
    free(removed);
    --table->size;
    return true;
}

static void table_destroy(struct HashTable *table)
{
    if (table == NULL) return;

    for (size_t i = 0U; i < BUCKET_COUNT; ++i) {
        struct Entry *entry = table->buckets[i];
        while (entry != NULL) {
            struct Entry *next = entry->next;
            free(entry);
            entry = next;
        }
        table->buckets[i] = NULL;
    }
    table->size = 0U;
}

int main(void)
{
    struct HashTable table = { { NULL }, 0U };
    int value = 0;

    if (!table_put(&table, 10U, 100) ||
        !table_put(&table, 17U, 170) ||
        !table_put(&table, 24U, 240)) {
        table_destroy(&table);
        return 1;
    }

    if (table_get(&table, 17U, &value)) {
        printf("Key 17 has value %d\n", value);
    }

    if (!table_remove(&table, 17U)) {
        table_destroy(&table);
        return 2;
    }

    printf("Key 17 present after removal: %s\n",
           table_get(&table, 17U, &value) ? "yes" : "no");
    printf("Entries remaining: %zu\n", table.size);

    table_destroy(&table);
    return 0;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

enum { CAPACITY = 7 };
enum SlotState { EMPTY, OCCUPIED, DELETED };

struct Slot {
    unsigned int key;
    int value;
    enum SlotState state;
};

struct HashTable {
    struct Slot slots[CAPACITY];
    size_t size;
};

static size_t hash_index(unsigned int key)
{
    return (size_t)(key % CAPACITY);
}

static bool table_put(struct HashTable *table,
                      unsigned int key, int value)
{
    if (table == NULL) return false;

    size_t first_deleted = CAPACITY;
    size_t start = hash_index(key);

    for (size_t step = 0U; step < CAPACITY; ++step) {
        size_t index = (start + step) % CAPACITY;
        struct Slot *slot = &table->slots[index];

        if (slot->state == OCCUPIED && slot->key == key) {
            slot->value = value;
            return true;
        }
        if (slot->state == DELETED && first_deleted == CAPACITY) {
            first_deleted = index;
        }
        if (slot->state == EMPTY) {
            size_t destination =
                first_deleted != CAPACITY ? first_deleted : index;
            table->slots[destination].key = key;
            table->slots[destination].value = value;
            table->slots[destination].state = OCCUPIED;
            ++table->size;
            return true;
        }
    }

    if (first_deleted != CAPACITY) {
        table->slots[first_deleted].key = key;
        table->slots[first_deleted].value = value;
        table->slots[first_deleted].state = OCCUPIED;
        ++table->size;
        return true;
    }
    return false;
}

static bool table_get(const struct HashTable *table,
                      unsigned int key, int *value_out)
{
    if (table == NULL || value_out == NULL) return false;

    size_t start = hash_index(key);
    for (size_t step = 0U; step < CAPACITY; ++step) {
        size_t index = (start + step) % CAPACITY;
        const struct Slot *slot = &table->slots[index];

        if (slot->state == EMPTY) return false;
        if (slot->state == OCCUPIED && slot->key == key) {
            *value_out = slot->value;
            return true;
        }
    }
    return false;
}

static bool table_remove(struct HashTable *table, unsigned int key)
{
    if (table == NULL) return false;

    size_t start = hash_index(key);
    for (size_t step = 0U; step < CAPACITY; ++step) {
        size_t index = (start + step) % CAPACITY;
        struct Slot *slot = &table->slots[index];

        if (slot->state == EMPTY) return false;
        if (slot->state == OCCUPIED && slot->key == key) {
            slot->state = DELETED;
            --table->size;
            return true;
        }
    }
    return false;
}

int main(void)
{
    struct HashTable table = { { { 0U, 0, EMPTY } }, 0U };
    int value = 0;

    if (!table_put(&table, 10U, 100) ||
        !table_put(&table, 17U, 170) ||
        !table_put(&table, 24U, 240)) {
        return 1;
    }

    if (!table_remove(&table, 17U)) return 2;

    if (table_get(&table, 24U, &value)) {
        printf("Key 24 remains reachable with value %d\n", value);
    }

    if (!table_put(&table, 31U, 310)) return 3;
    printf("Key 31 inserted into the available probe sequence\n");
    printf("Entries remaining: %zu\n", table.size);
    return 0;
}
